  ('djs-dhol','services','Services','multiselect','[{"value":"dj","label":"DJ","seo":"dj"},{"value":"dhol","label":"Dhol","seo":"dhol"},{"value":"sound","label":"Sound and lights","seo":"sound"}]',true,true,true,'What does {name} provide?',null,1),
