-- ---------------------------------------------------------------- towns: state codes, districts, centres
-- First run only: these towns open launched; Ops launches the rest of India town by town.
update mkt.cities c set state_code = v.code, district = v.district, lat = v.lat, lng = v.lng, launched = true
from (values
  ('chandigarh', '04', 'Chandigarh', 30.73330, 76.77940), ('mohali', '03', 'SAS Nagar (Mohali)', 30.70460, 76.71790),
  ('panchkula', '06', 'Panchkula', 30.69420, 76.86060), ('zirakpur', '03', 'SAS Nagar (Mohali)', 30.64250, 76.81730),
  ('kharar', '03', 'SAS Nagar (Mohali)', 30.74640, 76.64530), ('new-chandigarh', '03', 'SAS Nagar (Mohali)', 30.79220, 76.71870),
  ('dera-bassi', '03', 'SAS Nagar (Mohali)', 30.58720, 76.84280), ('ludhiana', '03', 'Ludhiana', 30.90100, 75.85730),
  ('delhi', '07', 'Delhi', 28.61390, 77.20900)
) as v(slug, code, district, lat, lng)
